#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <IOKit/IOKitLib.h>
#include <IOKit/hid/IOHIDManager.h>
#include <IOKit/hid/IOHIDDevice.h>
#include <IOKit/hid/IOHIDQueue.h>

typedef struct {
    float x;
    float y;
} Point;

void sendTouchEvent(float x, float y) {
    // Try to get the HID manager
    IOHIDManagerRef manager = IOHIDManagerCreate(kCFAllocatorDefault, kIOHIDOptionsTypeNone);

    if (!manager) {
        printf("Failed to create HID manager\n");
        return;
    }

    IOHIDManagerSetDeviceMatching(manager, NULL);
    IOHIDManagerOpen(manager, kIOHIDOptionsTypeNone);

    // Get all HID devices
    CFSetRef devices = IOHIDManagerCopyDevices(manager);

    printf("Touch event would be sent to: %.0f, %.0f\n", x, y);
    printf("HID devices found: %ld\n", devices ? CFSetGetCount(devices) : 0);

    CFRelease(manager);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("Usage: tap_hid <x> <y>\n");
        return 1;
    }

    float x = atof(argv[1]);
    float y = atof(argv[2]);

    sendTouchEvent(x, y);

